import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"快捷键","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/shortcuts.md","filePath":"zh/guide/shortcuts.md","lastUpdated":1792800661000}'),r={name:"zh/guide/shortcuts.md"};function l(c,t,i,h,s,n){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h1><p>本页列出 MeetCue 的全局快捷键并说明如何修改。焦点在会议软件上时这些快捷键同样有效。</p><h2 id="默认快捷键" tabindex="-1">默认快捷键 <a class="header-anchor" href="#默认快捷键" aria-label="Permalink to &quot;默认快捷键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>动作</th></tr></thead><tbody><tr><td><code>Ctrl+Alt+Space</code></td><td>开始 / 暂停拾取</td></tr><tr><td><code>Ctrl+Alt+H</code></td><td>面板：完整 → 迷你条 → 隐藏</td></tr><tr><td><code>Ctrl+Alt+[</code></td><td>上一问</td></tr><tr><td><code>Ctrl+Alt+]</code></td><td>下一问（练习中为跳过当前题）</td></tr><tr><td><code>Ctrl+Alt+Enter</code></td><td>把当前问题标为已答</td></tr></tbody></table><h2 id="为什么选这些键" tabindex="-1">为什么选这些键 <a class="header-anchor" href="#为什么选这些键" aria-label="Permalink to &quot;为什么选这些键&quot;">​</a></h2><p>默认键位避开了 Windows 笔记本上常见的快捷键：</p><ul><li>会议软件常用的 <code>Ctrl+Shift</code> 组合，例如 Teams 的静音；</li><li>输入法使用的 <code>Ctrl+Space</code> 或 <code>Shift+Space</code>；</li><li>显卡驱动用于旋转屏幕的 <code>Ctrl+Alt</code> 加方向键；</li><li>聊天软件使用的 <code>Ctrl+Alt+A</code>、<code>Ctrl+Alt+W</code>、<code>Ctrl+Alt+Z</code>；</li><li>功能键，很多笔记本默认把它们当作媒体键。</li></ul><h2 id="修改快捷键" tabindex="-1">修改快捷键 <a class="header-anchor" href="#修改快捷键" aria-label="Permalink to &quot;修改快捷键&quot;">​</a></h2><ol><li>打开 <strong>设置 › 快捷键</strong>。</li><li>点击对应动作旁的 <strong>修改</strong>。</li><li>按下新的组合键。按 <code>Esc</code> 取消。</li></ol><p>如果该组合已被其他程序占用，这一行会标红并显示 <a href="/meetcue/zh/troubleshooting/error-codes#mc-hk-001">MC-HK-001</a>，请换一个组合。<strong>恢复默认</strong> 会还原上表的键位。</p><h2 id="快捷键收不到的情况" tabindex="-1">快捷键收不到的情况 <a class="header-anchor" href="#快捷键收不到的情况" aria-label="Permalink to &quot;快捷键收不到的情况&quot;">​</a></h2><p>前台窗口是以管理员身份运行的程序，或独占全屏的游戏时，Windows 不会把快捷键传给 MeetCue。参见<a href="/meetcue/zh/troubleshooting/panel">快捷键与悬浮窗</a>。</p>',12)])])}const _=e(r,[["render",l]]);export{p as __pageData,_ as default};
